WITH flattened AS (SELECT id, plan, currency, EXPLODE_OUTER(tier_limits) AS element FROM price_tiers), filtered AS (SELECT *, CAST(element AS DOUBLE) AS element_num FROM flattened WHERE plan != 'basic'), cleaned AS (SELECT currency, element, element_num, element_num + element AS element_num_plus_element, CASE WHEN plan = 'pro' THEN 1 ELSE 0 END AS is_pro FROM filtered WHERE currency = 'USD'), valid AS (SELECT *, is_pro + element AS is_pro_plus_element, ROUND(element_num, 2) AS element_num_rounded FROM cleaned WHERE element_num BETWEEN 33 AND 55), scored AS (SELECT element, element_num, element_num_plus_element, is_pro, is_pro_plus_element, STDDEV_SAMP(element) OVER (PARTITION BY currency) AS currency_stddev_samp_element FROM valid WHERE element_num > 58) SELECT element_num FROM scored ORDER BY element_num
